use std::cell::Cell;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread;

thread_local! {
    static COUNTER: Cell<u32> = const { Cell::new(0) };
}

fn main() {
    // park / unpark: sleep until another thread says so (loop: wake-ups can be spurious)
    let ready = Arc::new(AtomicBool::new(false));
    let flag = Arc::clone(&ready);
    let waiter = thread::spawn(move || {
        while !flag.load(Ordering::Acquire) {
            thread::park();
        }
        "woken"
    });
    ready.store(true, Ordering::Release);
    waiter.thread().unpark();
    assert_eq!(waiter.join().unwrap(), "woken");

    // yield_now is a hint to the scheduler, with no visible result
    thread::yield_now();

    // is_finished is true once the closure has returned
    let done = thread::spawn(|| 1);
    while !done.is_finished() {
        thread::yield_now();
    }
    assert_eq!(done.join().unwrap(), 1);

    // an unnamed thread has no name; ids are unique per thread
    let id_here = thread::current().id();
    let id_there = thread::spawn(|| thread::current().id()).join().unwrap();
    assert_ne!(id_here, id_there);
    // thread_local!: every thread has its own copy, starting fresh
    COUNTER.set(10);
    let theirs = thread::spawn(|| {
        COUNTER.set(COUNTER.get() + 1);
        COUNTER.get()
    })
    .join()
    .unwrap();
    assert_eq!((theirs, COUNTER.get()), (1, 10));
    println!("others hold");
}

check-scope-panic.rs.code:
use std::panic::{self, AssertUnwindSafe};
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread;

fn main() {
    panic::set_hook(Box::new(|_| {})); // keep the expected panics quiet

    // a scoped thread that panics and is never joined: the scope itself panics
    let outcome = panic::catch_unwind(AssertUnwindSafe(|| {
        thread::scope(|s| {
            s.spawn(|| panic!("inside the scope"));
        });
    }));
    let payload = outcome.expect_err("the scope should have panicked");
    let text = payload.downcast_ref::<&str>().copied().unwrap_or("");
    assert_eq!(text, "a scoped thread panicked");

    // joined by hand: the scope returns normally and join holds the Err
    let joined = thread::scope(|s| s.spawn(|| panic!("inside the scope")).join().is_err());
    assert!(joined);
    // a panic does not cancel the sibling threads: the scope waits for them to finish
    let sibling_finished = AtomicBool::new(false);
    let outcome = panic::catch_unwind(AssertUnwindSafe(|| {
        thread::scope(|s| {
            s.spawn(|| panic!("inside the scope"));
            s.spawn(|| {
                thread::yield_now();
                sibling_finished.store(true, Ordering::SeqCst);
            });
        });
    }));
    assert!(outcome.is_err());
    assert!(sibling_finished.load(Ordering::SeqCst));
    println!("scope facts hold");
}

